import pandas as pd,numpy as np
from scipy.optimize import least_squares
def load(f):
    d=pd.read_csv(f); return {k:d[c].values for k,c in [('t','time_s'),('P','active_power_pu'),('Q','reactive_power_pu'),('V','voltage_pu'),('th','bus_angle_rad'),('Vs','voltage_setpoint_pu')]}
def simQ(p,D):
    a,b,TQ=p
    V,Vs,t=D['V'],D['Vs'],D['t']; dt=t[1]-t[0]
    V0,Vs0,Q0=V[0],Vs[0],D['Q'][0]
    Qm=Q0; out=np.zeros(len(t))
    for i in range(len(t)):
        out[i]=Qm
        tgt=Q0+a*(V[i]-V0)+b*(Vs[i]-Vs0)
        Qm+=dt*(tgt-Qm)/TQ
    return out
names=['A2_amb_op1','A2_amb_op2','A2_vref_op1','A2_vref_op3','A2_line_op3','A2_load_op2']
Ds=[load(f'train/{n}.csv') for n in names]
def res(p):
    return np.concatenate([simQ(p,D)[::2]-D['Q'][::2] for D in Ds])
