import json,numpy as np
p=np.load('p2.npy')
names=['XL','mq','mp','kiv','kpv','TPf','TQf','TVf']
params={k:float(v) for k,v in zip(names,p)}
params['w0']=2*np.pi*60
sub={
 "params":params,
 "defs":{
   "a0":"atan2(P0*XL, Q0*XL+V0**2)",
   "E0":"sqrt((Q0*XL+V0**2)**2+(P0*XL)**2)/V0",
   "Vcmd":"Vset + mq*(Q0-Qm)",
   "E":"Min(Max(kpv*(Vcmd-Vm)+xv,0),1.15)",
   "Pd":"V*E*sin(dl-theta)/XL",
   "Qd":"(V*E*cos(dl-theta)-V**2)/XL"
 },
 "states":{
   "Pm":{"rhs":"(Pd-Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Qd-Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V-Vm)/TVf","init":"V0"},
   "dl":{"rhs":"w0*mp*(P0-Pm)","init":"theta0+a0"},
   "xv":{"rhs":"kiv*(Vcmd-Vm)","init":"E0"}
 },
 "outputs":{"P":"Pd","Q":"Qd"}
}
json.dump(sub,open('submission.json','w'),indent=1)
print(open('submission.json').read()[:400])
